// Guards against releasing a build configured for a local deployment
// (the env files are generated by pundit-deployment/scripts/render-env.sh).

const fs = require('fs');
const path = require('path');
const { ENVIRONMENTS } = require('./config');

const ROOT = path.join(__dirname, '../..');
const HOST_RE = /https?:\/\/([^/'"`\s?#:]+)/g;

const extractHosts = (text) => [
  ...new Set([...text.matchAll(HOST_RE)].map((m) => m[1].toLowerCase())),
];

const isLocalHost = (host) => host === 'localhost'
  || host === '0.0.0.0'
  || /^127\./.test(host)
  || /\.(test|local|localhost)$/.test(host);

// files: { path: content | null } (null = file not found). Returns error messages.
const checkHosts = (env, files) => {
  const { apiHost, forbiddenApiHost, envFiles } = ENVIRONMENTS[env];
  const errors = [];
  Object.entries(envFiles).forEach(([file, required]) => {
    const content = files[file];
    if (content === null || content === undefined) {
      if (required) errors.push(`${file} is missing`);
      return;
    }
    const hosts = extractHosts(content);
    hosts.filter(isLocalHost).forEach((host) => {
      errors.push(`${file} points at the local host ${host}`);
    });
    if (hosts.includes(forbiddenApiHost)) {
      errors.push(`${file} contains ${forbiddenApiHost}, the API host of the other environment`);
    }
    if (!hosts.includes(apiHost)) {
      errors.push(`${file} does not contain the ${env} API host ${apiHost}`);
    }
  });
  return errors;
};

const readEnvFiles = (env) => Object.fromEntries(
  Object.keys(ENVIRONMENTS[env].envFiles).map((file) => {
    const fullPath = path.join(ROOT, file);
    return [file, fs.existsSync(fullPath) ? fs.readFileSync(fullPath, 'utf8') : null];
  }),
);

const checkEnvFiles = (env) => checkHosts(env, readEnvFiles(env));

module.exports = { extractHosts, isLocalHost, checkHosts, checkEnvFiles };
